#[component]
pub fn BrandLogo(
    icon: SimpleIcon,
    #[props(optional)] size: Option<u32>,
    #[props(optional)] class: Option<String>,
) -> Element {
    let size = size.unwrap_or(24);
    rsx! {
        svg {
            class: format!("text-seasalt-400 {}", class.unwrap_or_default()),
            view_box: "0 0 24 24",
            "aria-hidden": "true",
            width: {size},
            height: {size},
            fill: "currentColor",
            path { d: {icon.path} }
        }
    }
}
